<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { listGames } from '../api/client'
import { useGameStore } from '../stores/game'
import NarrativeTurn from '../components/NarrativeTurn.vue'
import CreateGameFlow from '../components/CreateGameFlow.vue'

type Phase = 'selection' | 'initialization' | 'play' | 'saves'
const route = useRoute(); const router = useRouter(); const store = useGameStore(); const saves = ref<Awaited<ReturnType<typeof listGames>>>([]); const phase = computed<Phase>(() => route.query.phase === 'saves' ? 'saves' : route.params.gameId ? 'play' : 'selection'); const answer = ref(''); const error = ref(''); const busy = ref(false)
const currentWorld = computed(() => store.game?.world)
async function loadSaved(gameId: string) { busy.value = true; try { await store.load(gameId); await router.replace(`/game/${encodeURIComponent(gameId)}`) } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法加载存档。' } finally { busy.value = false } }
function choose(label: string) { void store.speak(label) }
onMounted(async () => { try { if (phase.value === 'play' && route.params.gameId) await loadSaved(String(route.params.gameId)); else if (phase.value === 'saves') saves.value = await listGames() } catch (cause) { error.value = cause instanceof Error ? cause.message : '页面数据加载失败。' } })
</script>
<template>
  <CreateGameFlow v-if="phase === 'selection' || phase === 'initialization'" />
  <section v-else-if="phase === 'saves'" class="page-content game-flow"><div class="section-heading"><div><p class="eyebrow">SAVES</p><h1>加载存档</h1><p class="lede">选择一局继续游玩。</p></div><button class="quiet-button" type="button" @click="router.push('/')">返回首页</button></div><div class="save-list"><button v-for="save in saves" :key="save.gameId" class="save-row" type="button" @click="loadSaved(save.gameId)"><strong>{{ save.gameId }}</strong><span>{{ save.worldId }} · {{ save.engineId || '纯叙事' }}</span><small>第 {{ save.day }} 天 · revision {{ save.revision }} · {{ save.updatedAt }}</small></button><p v-if="!saves.length" class="empty-timeline">暂无存档。</p></div></section>
  <section v-else-if="store.game" class="play-page"><div class="play-header"><div><p class="eyebrow">{{ store.game.rulesetId || 'NARRATIVE' }} / REVISION {{ store.game.revision }}</p><h1>{{ currentWorld?.setting || '当前世界' }}</h1><p>{{ currentWorld?.settingDescription || 'GM 正在等待你的选择。' }}</p></div><div class="play-actions"><button class="quiet-button" type="button" @click="router.push('/')">退出</button><button class="secondary-button" type="button" @click="store.save">保存游戏</button></div></div><div v-if="store.error || store.notice" class="message-bar" :class="{ error: store.error }">{{ store.error || store.notice }}</div><div class="play-layout"><main class="story-column"><div class="story-heading"><h2>GM 对话</h2><span class="revision-badge">第 {{ currentWorld?.day }} 天</span></div><div class="timeline"><article v-for="item in store.events" :key="item.id" class="timeline-item" :class="item.kind"><div class="timeline-marker" /><div class="timeline-copy"><strong>{{ item.title }}</strong><p>{{ item.detail }}</p></div></article></div><NarrativeTurn v-if="store.narration" :turn="store.narration" :acting="store.acting" @choose="choose" /><div class="free-input"><input v-model="answer" placeholder="告诉 GM 你要做什么" @keyup.enter="store.speak(answer); answer = ''" /><button class="primary-button" type="button" :disabled="store.acting || !answer.trim()" @click="store.speak(answer); answer = ''">发送</button></div></main><aside class="status-column"><section class="status-panel"><p class="panel-kicker">WORLD STATE</p><h2>当前状态</h2><dl class="world-facts"><div><dt>位置</dt><dd>{{ currentWorld?.location || '未指定' }}</dd></div><div><dt>区域</dt><dd>{{ currentWorld?.currentRegion || '未指定' }}</dd></div><div><dt>天气</dt><dd>{{ currentWorld?.weather || '未指定' }}</dd></div><div><dt>威胁</dt><dd>{{ currentWorld?.threatLevel || '未知' }}</dd></div></dl><div class="quest-callout"><span>主线方向</span><strong>{{ currentWorld?.mainQuest || '尚未确定' }}</strong></div></section><section v-if="store.game.rulesetState" class="status-panel"><p class="panel-kicker">ENGINE STATE</p><pre class="engine-state">{{ JSON.stringify(store.game.rulesetState, null, 2) }}</pre></section></aside></div></section>
</template>
